/* VELVET CASKET (theme author guide v1.5, contract 1)
   One idea: every container is a coffin. Messages stand as upright coffins with a finial on the
   head, the message box is a coffin laid on its side, Home widgets are a row of coffins, dialogs are
   coffin lids, buttons are coffin tags, avatars are mourning cameos, and an iron cemetery fence runs
   under the top bar.
   Day  = PASTEL GOTH: lilac, mint, baby pink, thick black sticker outlines, bats and bow-skulls.
   Night = TRADITIONAL GOTH: black and oxblood velvet, antique silver trim, iron crosses, candlelight. */

:root{
  --mari-tokens-version:1;
  /* coffin geometry (px so the shape survives any height) */
  --vc-head:22px;   /* how far the head is cut in from each side */
  --vc-sh:22px;     /* how far down the shoulders sit */
  --vc-foot:14px;   /* how far the foot tapers in */
  --vc-bw:2px;      /* outline thickness */
  --vc-coffin:polygon(var(--vc-head) 0,calc(100% - var(--vc-head)) 0,100% var(--vc-sh),calc(100% - var(--vc-foot)) 100%,var(--vc-foot) 100%,0 var(--vc-sh));
  --vc-coffin-in:polygon(calc(var(--vc-head) - 1px) 0,calc(100% - var(--vc-head) + 1px) 0,100% calc(var(--vc-sh) - 1px),calc(100% - var(--vc-foot)) 100%,var(--vc-foot) 100%,0 calc(var(--vc-sh) - 1px));
  /* coffin on its side: head on the left, foot on the right */
  --vc-coffin-side:polygon(0 12px,30px 0,calc(100% - 8px) 6px,100% 50%,calc(100% - 8px) calc(100% - 6px),30px 100%,0 calc(100% - 12px));
  /* coffin tag for buttons and pills */
  --vc-tag:polygon(8px 0,calc(100% - 8px) 0,100% 50%,calc(100% - 8px) 100%,8px 100%,0 50%);

  --vc-blackletter:"UnifrakturCook","Old English Text MT",serif;
  --vc-serif:"EB Garamond",Garamond,"Times New Roman",serif;
  --vc-plate:"Cormorant SC","EB Garamond",serif;

  --radius:2px;
  --mari-font-ui:var(--vc-serif);
  --mari-font-heading:var(--vc-blackletter);
  --mari-font-chat:var(--vc-serif);
  --ov-serif:var(--vc-blackletter);
  --mari-chat-font-size:17px;
  --mari-chat-line-height:1.6;
  --mari-message-measure:72ch;
  --mari-paragraph-gap:0.8em;
  --mari-dialogue-weight:500;
  --mari-text-outline:0;
  --mari-min-ui-text:12px;
  --mari-toast-font-size:1rem;
  --mari-selected-tint:var(--primary);
  --mari-msg-head-rule:var(--vc-head-rule);
  --mari-home-art:none;
  --mari-home-widget-radius:0;
  --mari-home-widget-border-width:0;
  --mari-home-widget-font:var(--vc-serif);
  --mari-home-widget-title-font:var(--vc-blackletter);
  --mari-home-widget-title-size:1.6rem;
  --mari-home-widget-eyebrow-size:0.8125rem;
  --mari-home-widget-text-size:0.9375rem;
  --mari-home-widget-action-size:0.9375rem;
  --mari-home-shortcut-size:1rem;
  --mari-top-bar-plate-radius:0;
  --mari-composer-placeholder:"Whisper into the dark...";
  --mari-chat-wash:none;
  --mari-chat-row-art-opacity:0;
  --marinara-theme-accent-pulse:none;
  --glow-primary:transparent; --glow-accent:transparent;
  --mari-chat-column:46rem;
  --mari-art-saturation-1:28%; --mari-art-saturation-2:24%;
  --mari-pinned-speaker:on;
  --mari-phone-avatar:hidden;
}

/* ── NIGHT · traditional goth ─────────────────────────────── */
:root,:root[data-theme="dark"]{
  --vc-ground:#07090b; --vc-ink:#efe6e8; --vc-mute:#bfaeb5; --vc-faint:#9a8a91;
  --vc-hair:rgba(185,170,180,.28);
  --vc-trim:#9a8f99;              /* antique silver outline */
  --vc-lining:#0a1017;            /* coffin lining under the velvet */
  --vc-lining-user:#0d151d;
  --vc-velvet:url("theme:velvet-tile.webp");
  --vc-panel:rgba(8,12,16,.92);
  --vc-bar:#070b0e;
  --vc-accent:#215fa3;            /* oxblood */
  --vc-accent-ink:#a7ccf1;        /* readable crimson for text on black */
  --vc-gold:#dcb874;              /* candle gold */
  --vc-finial:url("theme:or-cross.webp");
  --vc-finial-user:url("theme:or-rose.webp");
  --vc-finial-latest:url("theme:or-candle.webp");
  --vc-crest:url("theme:or-crest.webp");
  --vc-scene-break:url("theme:or-fleur.webp");
  --vc-fence:url("theme:fence-night.svg");
  --mari-icon-send:url("theme:send-night.svg");
  --vc-backdrop:url("theme:night-chapel.webp");
  --vc-backdrop-wash:linear-gradient(rgba(7,9,11,0),rgba(7,9,11,0));
  --mari-art-lightness-1:20%; --mari-art-lightness-2:12%;
  --vc-online:#4fc79a;
  --vc-name:var(--vc-gold);
  --vc-latest-trim:#215fa3;
  --vc-head-rule:1px solid rgba(185,170,180,.3);
  --vc-mint:#cfc6d2;
  --vc-mint-ink:#cfc6d2;
  --vc-rail:url("theme:rail-night.svg");
  --vc-lid:url("theme:lid-night.svg");
  --vc-sidebar-bg:linear-gradient(rgba(7,10,14,.28),rgba(7,10,14,.4)),url("theme:velvet-tile.webp") 0 0 / 512px repeat;
  --vc-lining-layers:linear-gradient(rgba(9,14,21,.5),rgba(9,14,21,.58)),var(--vc-velvet) 0 0 / 512px repeat,#0a1017;
  --vc-lining-user-layers:linear-gradient(rgba(12,22,34,.46),rgba(12,22,34,.54)),var(--vc-velvet) 0 0 / 512px repeat,#0d151d;
}

/* ── DAY · pastel goth ─────────────────────────────────────── */
:root[data-theme="light"]{
  --vc-ground:#e2effb; --vc-ink:#12263b; --vc-mute:#3a536c; --vc-faint:#526b83;
  --vc-hair:rgba(26,16,32,.22);
  --vc-trim:#1a1020;              /* thick black sticker outline */
  --vc-lining:#f2f8ff;            /* lilac paper */
  --vc-lining-user:#e0efff;       /* baby pink */
  --vc-velvet:none;
  --vc-panel:rgba(236,245,253,.93);
  --vc-bar:#e8f2fc;
  --vc-accent:#2d68b8;            /* hot baby-pink, white text passes */
  --vc-accent-ink:#2a507a;
  --vc-gold:#285d89;              /* mint ink for names */
  --vc-finial:url("theme:st-bat.webp");
  --vc-finial-user:url("theme:st-skull.webp");
  --vc-finial-latest:url("theme:st-heartbat.webp");
  --vc-crest:url("theme:st-holo.webp");
  --vc-scene-break:url("theme:st-holo.webp");
  --vc-fence:url("theme:fence-day.svg");
  --vc-bw:2.5px;
  --mari-icon-send:url("theme:send-day.svg");
  --vc-backdrop:url("theme:day-chapel.webp");
  --vc-backdrop-wash:linear-gradient(rgba(226,239,251,0),rgba(226,239,251,0));
  --mari-art-lightness-1:84%; --mari-art-lightness-2:78%;
  --vc-online:#17694a;
  --vc-name:#204f7b;
  --vc-mint:#a7d4f4;
  --vc-mint-ink:#235b86;
  --vc-latest-trim:#1a1020;
  --vc-head-rule:2px dashed #7bb9e6;
  --vc-rail:url("theme:rail-day.svg");
  --vc-lid:url("theme:lid-day.svg");
  --vc-sidebar-bg:linear-gradient(rgba(237,246,254,.9),rgba(237,246,254,.9)),url("theme:day-pattern.webp") 0 0 / 320px repeat;
  --vc-lining-layers:#dfedfc;
  --vc-lining-user-layers:#d4e8fc;
  --vc-lining-latest:linear-gradient(#dfedfc,#dfedfc) padding-box;
}

:root,:root[data-theme="dark"],:root[data-theme="light"]{
  --background:var(--vc-ground); --foreground:var(--vc-ink);
  --card:var(--vc-panel); --card-foreground:var(--vc-ink);
  --popover:var(--vc-panel); --popover-foreground:var(--vc-ink);
  --primary:var(--vc-accent); --primary-foreground:#fff;
  --secondary:color-mix(in srgb,var(--vc-ink) 8%,var(--vc-ground)); --secondary-foreground:var(--vc-ink);
  --muted:color-mix(in srgb,var(--vc-ink) 6%,var(--vc-ground)); --muted-foreground:var(--vc-mute);
  --accent:color-mix(in srgb,var(--vc-accent) 16%,var(--vc-ground)); --accent-foreground:var(--vc-ink);
  --destructive:#b3123a; --destructive-foreground:#fff;
  --border:var(--vc-hair); --input:var(--vc-hair); --ring:var(--vc-accent);
  --sidebar:var(--vc-panel); --sidebar-foreground:var(--vc-ink); --sidebar-border:var(--vc-hair);
  --sidebar-accent:color-mix(in srgb,var(--vc-accent) 14%,transparent); --sidebar-accent-foreground:var(--vc-ink);
  --ov-line:var(--vc-hair); --ov-text:var(--vc-ink); --ov-muted:var(--vc-mute); --ov-dim:var(--vc-faint);
  --ov-accent:var(--vc-accent-ink);
  --ov-hover:color-mix(in srgb,var(--vc-ink) 7%,transparent);
  --ov-active-bg:color-mix(in srgb,var(--vc-accent) 18%,transparent);
  --ov-mode-conversation:var(--vc-accent-ink); --ov-mode-roleplay:var(--vc-accent-ink); --ov-mode-game:var(--vc-gold);
  --mari-mode-conversation:var(--vc-accent-ink); --mari-mode-roleplay:var(--vc-accent-ink); --mari-mode-game:var(--vc-gold);
  --mari-home-pink:var(--vc-accent-ink); --mari-home-violet:var(--vc-gold);
  --mari-chrome-accent:var(--vc-accent-ink);
  --mari-chrome-muted:var(--vc-mute);
  --mari-message-time:var(--vc-faint);
  --mari-message-actions:var(--vc-mute);
  --mari-swipe-counter:var(--vc-mute);
  --mari-dialogue-color:var(--vc-accent-ink);
  --mari-home-widget-bg:transparent;
  --mari-home-widget-title-color:var(--vc-ink);
  --mari-home-widget-muted:var(--vc-mute);
  --mari-home-widget-eyebrow-color:var(--vc-accent-ink);
  --mari-home-wash:transparent;
  --mari-page-veil:color-mix(in srgb,var(--vc-ground) 82%,transparent);
  --mari-chat-header-bg:none;
  --mari-scrim:color-mix(in srgb,var(--vc-ground) 72%,transparent);
  --mari-top-bar-plate:color-mix(in srgb,var(--vc-ground) 88%,transparent);
  --mari-status-online:var(--vc-online); --mari-status-idle:var(--vc-gold); --mari-status-dnd:#c42d4a; --mari-status-offline:var(--vc-faint);
  --mari-gauge-ok:#3fb68b; --mari-gauge-warn:#d39b3a; --mari-gauge-danger:#c42d4a;
  --mari-game-combat:var(--vc-accent); --mari-game-combat-text:#fff;
  --mari-game-combat-bg:var(--vc-accent); --mari-game-combat-bg-hover:color-mix(in srgb,var(--vc-accent) 85%,#000); --mari-game-combat-border:var(--vc-accent);
  --mari-stage-empty-bg:var(--vc-backdrop-wash),var(--vc-backdrop) center bottom / cover no-repeat,var(--vc-ground);
  --mari-user-avatar-placeholder:radial-gradient(circle at 50% 38%,var(--vc-trim) 0 22%,transparent 23%),radial-gradient(ellipse 60% 40% at 50% 100%,var(--vc-trim) 0 70%,transparent 71%),var(--vc-lining);
  --mari-focus-ring-color:var(--vc-accent-ink);
  --mari-top-bar-bg:var(--vc-fence) 0 100% / auto 44px repeat-x,linear-gradient(var(--vc-bar),var(--vc-bar));
}
/* ── Backdrop: the same chapel and graveyard, pastel by day, candlelit by night ── */
:root{
  --mari-app-backdrop-layers:var(--vc-backdrop-wash),var(--vc-backdrop) center bottom / cover no-repeat,var(--vc-ground);
  --mari-user-avatar-image:var(--vc-cameo);
  --mari-card-art-placeholder:var(--vc-cameo) center / auto 70% no-repeat,var(--vc-card-ph);
}
:root,:root[data-theme="dark"]{ --vc-cameo:url("theme:cameo-night.webp"); --vc-card-ph:radial-gradient(ellipse at 50% 40%,#0d233a,#060c12 75%); }
:root[data-theme="light"]{ --vc-cameo:url("theme:cameo-day.webp"); --vc-card-ph:radial-gradient(ellipse at 50% 40%,#e7f3fc,#c5dff5 75%); }
